findings.codeql_raw_query:
/**
 * @name Unsafe pickle deserialization with user input
 * @description User input reaching pickle.loads can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/pickle-deserialization-taint
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PickleTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember(["load", "loads", "Unpickler"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PickleTaintFlow = TaintTracking::Global<PickleTaintConfig>;
import PickleTaintFlow::PathGraph

from PickleTaintFlow::PathNode source, PickleTaintFlow::PathNode sink
where PickleTaintFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe pickle deserialization from $@.", source.getNode(), "user input"
